// LoadPlanner component - displays cargo items, vehicle selection, and AI optimization
import React, { useState } from 'react';
import { vehicleData, cargoData, deliveryLocations } from '../data/mockData';
import './LoadPlanner.css';

// Route optimization using Nearest Neighbor algorithm
const optimizeRoute = (startLocation, stops, locations) => {
  if (stops.length <= 2) return { route: stops, distance: 0 };

  const getDistance = (loc1, loc2) => {
    const l1 = locations[loc1];
    const l2 = locations[loc2];
    if (!l1 || !l2) return Infinity;
    const R = 6371; // Earth's radius in km
    const dLat = (l2.lat - l1.lat) * Math.PI / 180;
    const dLon = (l2.lng - l1.lng) * Math.PI / 180;
    const a = Math.sin(dLat/2) * Math.sin(dLat/2) +
              Math.cos(l1.lat * Math.PI / 180) * Math.cos(l2.lat * Math.PI / 180) *
              Math.sin(dLon/2) * Math.sin(dLon/2);
    return R * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1-a));
  };

  const visited = new Set([startLocation]);
  const route = [startLocation];
  let current = startLocation;
  let totalDistance = 0;

  while (visited.size < stops.length) {
    let nearest = null;
    let minDist = Infinity;

    for (const stop of stops) {
      if (!visited.has(stop)) {
        const dist = getDistance(current, stop);
        if (dist < minDist) {
          minDist = dist;
          nearest = stop;
        }
      }
    }

    if (nearest) {
      visited.add(nearest);
      route.push(nearest);
      totalDistance += minDist;
      current = nearest;
    }
  }

  return { route, distance: Math.round(totalDistance) };
};

function LoadPlanner() {
  const [selectedTruck, setSelectedTruck] = useState(vehicleData[0]);
  const [isOptimizing, setIsOptimizing] = useState(false);
  const [optimizationResult, setOptimizationResult] = useState(null);
  const [selectedCargo, setSelectedCargo] = useState(new Set(selectedTruck.cargo));

  // Get cargo details for selected truck
  const truckCargo = cargoData.filter(c => selectedTruck.cargo.includes(c.id));
  const totalWeight = truckCargo.reduce((sum, c) => sum + c.weight, 0);
  const capacityUsed = (totalWeight / (selectedTruck.capacity / 1000)) * 100;

  // Get priority color
  const getPriorityColor = (priority) => {
    switch(priority) {
      case 'high': return '#ef4444';
      case 'medium': return '#f59e0b';
      case 'low': return '#48bb78';
      default: return '#6b7280';
    }
  };

  // Handle truck selection change
  const handleTruckChange = (truckId) => {
    const truck = vehicleData.find(v => v.id === truckId);
    if (truck) {
      setSelectedTruck(truck);
      setSelectedCargo(new Set(truck.cargo));
      setOptimizationResult(null);
    }
  };

  // Handle AI optimization
  const handleOptimize = () => {
    setIsOptimizing(true);

    setTimeout(() => {
      // Run nearest neighbor algorithm
      const result = optimizeRoute(
        selectedTruck.routeStops[0],
        selectedTruck.routeStops,
        deliveryLocations
      );

      // Calculate savings
      const originalDistance = selectedTruck.totalDistance;
      const optimizedDistance = result.distance || originalDistance * 0.85;
      const distanceSaved = originalDistance - optimizedDistance;
      const timeSaved = Math.round(distanceSaved / 50 * 60); // Assuming 50km/h avg
      const fuelSaved = Math.round(distanceSaved / 5); // 5 km/L average

      setOptimizationResult({
        originalRoute: selectedTruck.routeStops,
        optimizedRoute: result.route,
        distanceSaved: Math.round(distanceSaved),
        timeSaved,
        fuelSaved,
        costSaved: fuelSaved * 95, // ₹95 per liter
        loadBalance: 'Optimized for weight distribution',
        fragileFirst: truckCargo.some(c => c.fragile)
      });

      setIsOptimizing(false);
    }, 1500);
  };

  return (
    <div className="load-planner">
      {/* Header */}
      <div className="planner-header">
        <div className="header-left">
          <h2>Load & Route Optimizer</h2>
          <p className="subtitle">AI-powered truck load optimization with route sequencing</p>
        </div>
        <div className="header-right">
          <div className="truck-selector-dropdown">
            <label>Select Truck:</label>
            <select 
              value={selectedTruck.id}
              onChange={(e) => handleTruckChange(e.target.value)}
              className="truck-select"
            >
              {vehicleData.filter(v => v.status !== 'maintenance').map(truck => (
                <option key={truck.id} value={truck.id}>
                  {truck.id} - {truck.driver} ({truck.type})
                </option>
              ))}
            </select>
          </div>
        </div>
      </div>

      {/* Main Content */}
      <div className="planner-content">
        {/* Left Panel - Truck & Cargo Info */}
        <div className="info-panel">
          {/* Truck Info Card */}
          <div className="truck-info-card">
            <div className="card-header">
              <h3>Truck Details</h3>
              <span className={`status-badge ${selectedTruck.status}`}>{selectedTruck.status}</span>
            </div>
            <div className="truck-stats">
              <div className="stat-row">
                <span className="stat-label">Driver</span>
                <span className="stat-value">{selectedTruck.driver}</span>
              </div>
              <div className="stat-row">
                <span className="stat-label">Capacity</span>
                <span className="stat-value">{selectedTruck.capacity / 1000} tons</span>
              </div>
              <div className="stat-row">
                <span className="stat-label">Current Load</span>
                <span className="stat-value">{totalWeight} kg ({capacityUsed.toFixed(1)}%)</span>
              </div>
              <div className="stat-row">
                <span className="stat-label">Fuel</span>
                <span className="stat-value">{selectedTruck.fuel}%</span>
              </div>
            </div>

            {/* Capacity Bar */}
            <div className="capacity-bar-container">
              <div className="capacity-label">Load Capacity</div>
              <div className="capacity-bar">
                <div 
                  className="capacity-fill"
                  style={{ 
                    width: `${Math.min(capacityUsed, 100)}%`,
                    background: capacityUsed > 90 ? '#ef4444' : capacityUsed > 70 ? '#f59e0b' : '#10b981'
                  }}
                />
              </div>
              <div className="capacity-text">{selectedTruck.loadUtilization}% utilized</div>
            </div>
          </div>

          {/* Cargo List */}
          <div className="cargo-list-card">
            <div className="card-header">
              <h3>Cargo Manifest</h3>
              <span className="cargo-count">{truckCargo.length} items</span>
            </div>
            <div className="cargo-items">
              {truckCargo.length > 0 ? truckCargo.map(item => (
                <div key={item.id} className="cargo-item-row">
                  <div className="cargo-info-left">
                    <span className="cargo-id">{item.id}</span>
                    <span className="cargo-name">{item.name}</span>
                  </div>
                  <div className="cargo-info-right">
                    {item.fragile && <span className="badge fragile">Fragile</span>}
                    <span className="badge" style={{ background: getPriorityColor(item.priority) }}>
                      {item.priority}
                    </span>
                    <span className="cargo-weight">{item.weight} kg</span>
                  </div>
                </div>
              )) : (
                <div className="empty-cargo">No cargo assigned to this truck</div>
              )}
            </div>
          </div>
        </div>

        {/* Right Panel - Route & Visualization */}
        <div className="visualization-panel">
          {/* Route Sequence */}
          <div className="route-card">
            <div className="card-header">
              <h3>Route Sequence</h3>
              <button 
                className={`optimize-btn ${isOptimizing ? 'loading' : ''}`}
                onClick={handleOptimize}
                disabled={isOptimizing || selectedTruck.routeStops.length < 2}
              >
                {isOptimizing ? (
                  <>
                    <div className="spinner"></div>
                    Optimizing...
                  </>
                ) : (
                  <>
                    <svg width="16" height="16" viewBox="0 0 24 24" fill="none">
                      <path d="M12 2L2 7L12 12L22 7L12 2Z" stroke="currentColor" strokeWidth="2"/>
                      <path d="M2 17L12 22L22 17" stroke="currentColor" strokeWidth="2"/>
                      <path d="M2 12L12 17L22 12" stroke="currentColor" strokeWidth="2"/>
                    </svg>
                    Optimize with AI
                  </>
                )}
              </button>
            </div>

            {/* Route visualization */}
            <div className="route-visualization">
              <div className="route-stops">
                {(optimizationResult?.optimizedRoute || selectedTruck.routeStops).map((stop, index) => (
                  <div key={index} className={`route-stop ${index < selectedTruck.currentStopIndex ? 'completed' : ''}`}>
                    <div className="stop-number">{index + 1}</div>
                    <div className="stop-connector" />
                    <div className="stop-details">
                      <span className="stop-name">{stop}</span>
                      <span className="stop-city">{deliveryLocations[stop]?.city || ''}</span>
                    </div>
                    {index < selectedTruck.currentStopIndex && (
                      <div className="stop-status">✓</div>
                    )}
                  </div>
                ))}
              </div>
            </div>
          </div>

          {/* Optimization Results */}
          {optimizationResult && (
            <div className="results-card">
              <div className="card-header">
                <h3>Optimization Results</h3>
                <span className="success-badge">✓ Optimized</span>
              </div>

              <div className="metrics-grid">
                <div className="metric-box">
                  <span className="metric-value">{optimizationResult.distanceSaved} km</span>
                  <span className="metric-label">Distance Saved</span>
                </div>
                <div className="metric-box">
                  <span className="metric-value">{optimizationResult.timeSaved} min</span>
                  <span className="metric-label">Time Saved</span>
                </div>
                <div className="metric-box">
                  <span className="metric-value">{optimizationResult.fuelSaved} L</span>
                  <span className="metric-label">Fuel Saved</span>
                </div>
                <div className="metric-box highlight">
                  <span className="metric-value">₹{optimizationResult.costSaved.toLocaleString()}</span>
                  <span className="metric-label">Cost Saved</span>
                </div>
              </div>

              <div className="optimization-notes">
                <div className="note">
                  <span className="note-icon">✓</span>
                  <span>Route resequenced using Nearest Neighbor algorithm</span>
                </div>
                {optimizationResult.fragileFirst && (
                  <div className="note">
                    <span className="note-icon">✓</span>
                    <span>Fragile items placed for minimal handling</span>
                  </div>
                )}
                <div className="note">
                  <span className="note-icon">✓</span>
                  <span>Weight distribution optimized for stability</span>
                </div>
              </div>
            </div>
          )}

          {/* Truck bed visualization */}
          <div className="truck-bed-card">
            <div className="card-header">
              <h3>Load Visualization</h3>
            </div>
            <div className="truck-bed-viz">
              <div className="truck-cab-viz">
                <div className="cab-window"></div>
              </div>
              <div className="truck-cargo-viz">
                {truckCargo.length > 0 ? (
                  <div className="cargo-grid">
                    {truckCargo.map((item, idx) => (
                      <div 
                        key={item.id}
                        className={`cargo-block ${optimizationResult ? 'optimized' : ''}`}
                        style={{ 
                          '--color': getPriorityColor(item.priority),
                          '--delay': `${idx * 0.1}s`
                        }}
                      >
                        <span className="block-label">{item.id.split('-')[1]}</span>
                      </div>
                    ))}
                  </div>
                ) : (
                  <div className="empty-truck">Empty</div>
                )}
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

export default LoadPlanner;
